mapper.select:
SELECT ranked.post_id, ranked.url, ranked.sort_order FROM ( SELECT pi.post_id, pi.url, pi.sort_order, ROW_NUMBER() OVER ( PARTITION BY pi.post_id ORDER BY pi.sort_order ASC ) AS rn FROM post_image pi WHERE pi.post_id IN
#{postId}
) ranked WHERE ranked.rn <= 3 ORDER BY ranked.post_id ASC, ranked.sort_order ASC
